(function(){'use strict';
const C=TrailContent,E=TrailEngine,KEY='study-trail-v1',$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.fresh(),storageBlocked=false,lastResult=null,pendingImport=null;
const recovery=TrailStorage.create({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},E.validate);
function recoveryPanel(){try{const item=recovery.inspect();if(!item)return '';return `<div class="card"><h2>置き換える前の記録</h2><p>${item.state?esc(item.state.name)+' · '+item.state.sessions.length+'セット':'読み取れなかった元のデータ'}を退避しています（${fmt(item.at)}）。この退避も同じブラウザ内にあるため、ファイルでのバックアップも続けてください。</p><div class="row">${item.state?'<button class="secondary" id="undo-restore">置き換える前に戻す</button>':''}<button class="secondary" id="export-recovery">退避記録を書き出す</button></div></div>`;}catch(e){return '<div class="card"><p>退避記録を読み込めません。現在の記録をファイルでバックアップしてください。</p></div>';}}
let filters={subject:'',sub:'',grade:'',query:'',due:false,scope:false},collectionLimit=24;
try{const raw=localStorage.getItem(KEY);if(raw)state=E.validate(JSON.parse(raw));}catch(e){storageBlocked=true;$('storage-warning').textContent='保存された記録を読み込めませんでした。上書きを止めています。「記録・設定」から保存済みデータを救出するか、バックアップを復元してください。';}
function save(){if(storageBlocked)return false;try{localStorage.setItem(KEY,JSON.stringify(state));$('storage-warning').textContent='';return true;}catch(e){$('storage-warning').textContent='保存できません。現在の画面では学習できますが、閉じる前に「記録・設定」からバックアップしてください。';return false;}}
const unit=id=>C.units.find(u=>u.id===id),award=id=>E.awards.find(a=>a.id===id),fmt=t=>new Date(t).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500);}
function modal(title,body){$('dialog-content').innerHTML=`<h2>${esc(title)}</h2>${body}`;$('dialog').showModal();}
$('close-dialog').onclick=()=>$('dialog').close();$('family').onclick=()=>go('family');
function go(page){location.hash=page;render();window.scrollTo(0,0);}
function levelCard(){const l=E.mageLevel(state);return `<section class="level-card"><div class="level-head"><div><div class="eyebrow">MAGE LEVEL</div><span class="level-num">Lv. ${l.level}</span> <span class="pill">${l.rank}</span></div><small>次のレベルまで ${l.remaining} XP</small></div><div class="progress" role="progressbar" aria-label="次の魔法使いレベルまで" aria-valuenow="${Math.floor(l.percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${l.percent}%"></span></div><p>累計 ${l.xp} XP · 修練の積み重ねを表します。ポイントを交換しても減りません。</p></section>`;}
function numbers(){let p=E.totals(state);return `<div class="numbers"><div class="number"><small>今週の取り組み</small><strong>${p.week}<small>pt</small></strong></div><div class="number"><small>これまでの積み上げ</small><strong>${p.total}<small>pt</small></strong></div><div class="number"><small>交換できるポイント</small><strong>${p.balance}<small>pt</small></strong></div></div>`;}
function unitCard(u){let p=E.progress(state,u.id),d=E.unitStatus(state,u.id);return `<a class="unit" style="--unit-color:${u.color}" href="#unit/${u.id}"><div class="unit-top"><span class="unit-icon">${u.icon}</span><div><small>${u.subject} · ${u.sub}</small><h3>${u.name}</h3></div></div><p>${u.summary}</p><div class="unit-bottom"><span>${d.isDue?'復習のころ · ':''}${p.label}</span><span>進む ↗</span></div></a>`;}
const art=`<div class="map-art grimoire-art" aria-hidden="true"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="magic-book"><span>✧</span><i></i><b>GRIMOIRE</b></div><span class="mote m1">✦</span><span class="mote m2">✧</span><span class="mote m3">✦</span></div>`;
function home(){return `<div class="intro"><div><div class="eyebrow">THE ATELIER OF SPELLS</div><h1>${esc(state.name)}の、次の一歩。</h1><p class="muted">今日は、どんな発見があるだろう。</p></div><span class="pill">自分のペースで進もう</span></div>${state.active?`<div class="notice row spread"><span>「${unit(state.active.unit).name}」の続きが残っています。</span><button data-resume>続きから再開 →</button></div>`:''}<section class="hero"><div><div class="eyebrow">TODAY'S PRACTICE</div><h2>知るほどに、<br>魔法は目を覚ます。</h2><p>知識を集め、考える力を磨く。<br>その先で、まだ見ぬ呪文があなたを待つ。</p><button data-start="">${state.active?'学習を再開する':'修練を始める'} →</button></div>${art}</section>${levelCard()}${numbers()}<div class="sectionhead"><h2>次に進む、知識の入口</h2><a href="#explore">全91単元を見る ↗</a></div><div class="grid">${E.recommendations(state).map(unitCard).join('')}</div><div class="sectionhead"><h2>魔導書からの便り</h2><a href="#collection">図鑑を開く ↗</a></div><div class="card row"><span style="font-size:38px;color:#b09036">◇</span><div><h3>${state.awards.length?`${state.awards.length}種の呪文が、あなたの手元に。`:'白紙の魔導書に、最初の呪文を。'}</h3><p class="muted">修練を重ねると、新しい術式が姿を現す。</p></div></div>`;}
function matchingUnits(){return C.units.filter(u=>(!filters.subject||u.subject===filters.subject)&&(!filters.sub||u.sub===filters.sub)&&(!filters.grade||u.grade===Number(filters.grade))&&(!filters.query||[u.name,u.subject,u.sub,u.lesson].join(' ').includes(filters.query))&&(!filters.due||E.unitStatus(state,u.id).isDue)&&(!filters.scope||(state.examScope||[]).includes(u.id)));}
function filterOptions(values,selected,all){return `<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('');}
function explore(){const subs=[...new Set(C.units.filter(u=>!filters.subject||u.subject===filters.subject).map(u=>u.sub))];return `<div class="intro"><div><div class="eyebrow">THE ARCHIVE</div><h1>どこからでも、進める。</h1><p class="muted">五教科 ${C.units.length}単元。学年は目安。未習の内容にも進めます。</p></div></div><div class="card"><h3>今日は、どんな考え方をしよう？</h3><div class="modegrid">${Object.entries(C.modes).map(([k,v])=>`<button data-mode="${k}">${v} →</button>`).join('')}</div><p class="subtle">おまかせ修練はテスト範囲・復習の時期・基礎とのつながりから選びます。</p></div><div class="card filters"><label>教科<select id="filter-subject">${filterOptions(['数学','英語','国語','理科','社会'],filters.subject,'すべての教科')}</select></label><label>サブ科目<select id="filter-sub">${filterOptions(subs,filters.sub,'すべてのサブ科目')}</select></label><label>学年の目安<select id="filter-grade">${filterOptions([1,2,3],filters.grade,'すべての学年')}</select></label><label class="search-label">単元・キーワード<input id="filter-query" type="search" value="${esc(filters.query)}" placeholder="例：方程式、植物、古文"></label><label class="checkline"><input type="checkbox" id="filter-due" ${filters.due?'checked':''}>復習の候補</label><label class="checkline"><input type="checkbox" id="filter-scope" ${filters.scope?'checked':''}>テスト範囲のみ</label></div><p id="filter-count" class="subtle">${matchingUnits().length}単元を表示 · テスト範囲は単元の入口で指定できます。</p><div class="grid" id="unit-results">${matchingUnits().map(unitCard).join('')||'<p class="muted">該当する単元がありません。絞り込みを変えてみてください。</p>'}</div><p class="subtle">主要単元の入口を収録しています。学校ごとの全範囲や発展問題、記述・図形作図・リスニングは拡充が必要です。</p>`;}
function unitPage(id){const u=unit(id);if(!u)return explore();let p=E.progress(state,id),d=E.unitStatus(state,id);return `<a class="previous" href="#explore">← 探索へ戻る</a><div class="intro"><div><div class="eyebrow">${u.subject} / ${u.sub}</div><h1>${u.name}</h1><p class="muted">${u.summary}</p><span class="pill">中${u.grade}目安</span></div></div><div class="card"><div class="row spread"><span class="pill">${p.label}</span><span class="muted">${p.count}回の挑戦</span></div><div class="evidence-grid">${Object.entries(C.modes).map(([k,v])=>`<span class="pill">${d.modes.includes(k)?'✓ ':'○ '}${v}</span>`).join('')}</div><p class="subtle">✓ はヒントなしの正解記録。理解の完成を示すものではありません。${d.isDue?'日を置いた復習の候補です。':''}</p>${u.prerequisites?.length?`<p class="subtle">つながる基礎：${u.prerequisites.map(id=>`<a href="#unit/${id}">${unit(id).name}</a>`).join(' ／ ')}<br>基礎が未学習でも、この単元へ進めます。</p>`:''}<label class="checkline"><input type="checkbox" data-exam-unit="${id}" ${(state.examScope||[]).includes(id)?'checked':''}>次のテスト範囲に入れる</label><p class="subtle">学校での学習状況は任意です。未習でも進めます。</p><div class="row"><button class="secondary" data-school="${id}:unlearned">${state.school[id]?.status==='unlearned'?'✓ ':''}まだ学校で習っていない</button><button class="secondary" data-school="${id}:learned">${state.school[id]?.status==='learned'?'✓ ':''}学校で習った</button></div><details><summary>考え方を読んでみる</summary><p class="lesson">${u.lesson}</p></details></div>${C.pilots[id]?`<div class="card"><h2>${u.name}の学習記録</h2><p class="subtle">${C.pilots[id].description}</p>${C.pilots[id].skills.map(k=>{const p=E.skillProgress(state,k.id);return `<div class="record row spread"><b>${k.name}</b><span>${p.label}${p.recheck?' · 再確認の候補':''}</span></div>`;}).join('')}<p class="subtle">以前の解答を新しい項目へ自動換算しません。${C.pilots[id].limitation}</p></div>`:''}<div class="card"><h2>この場所で挑戦する</h2><p class="subtle">異なる考え方を組み合わせたセット。完了した課題の数に応じてポイントが貯まります。</p><button data-start="${id}">いろいろな角度から →</button><div class="modegrid">${Object.entries(C.modes).map(([k,v])=>`<button data-start="${id}" data-start-mode="${k}">${v}</button>`).join('')}</div></div>`;}

function questionMedia(q){let out=q.diagram?TrailGeometry.render(q.diagram):'';if(q.table){const t=q.table;out+=`<div class="data-table"><table><caption>${esc(t.caption)}</caption><thead><tr>${t.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
if(q.graph){const g=q.graph;out+=`<figure class="wave-figure"><figcaption>波形A・B（横軸・縦軸の尺度は共通）</figcaption><svg viewBox="0 0 600 ${g.traces.length*150}" role="img" aria-label="同じ時間幅${g.durationMs}ミリ秒で記録した波形">${g.traces.map((t,i)=>{const y=i*150+65;let pts=[];for(let j=0;j<=500;j++)pts.push((65+j)+','+(y-20*t.amplitude*Math.sin(2*Math.PI*t.cycles*j/500)).toFixed(2));return `<text x="12" y="${y}" fill="currentColor">${esc(t.name)}</text><path d="M65 ${y-45} V${y+45} M65 ${y} H565" stroke="#8b829c" fill="none"/><polyline points="${pts.join(' ')}" fill="none" stroke="#e3c585" stroke-width="2.5"/><text x="62" y="${y+64}" fill="currentColor">0</text><text x="475" y="${y+64}" fill="currentColor">${g.durationMs} ms</text>`;}).join('')}</svg><details><summary>図の数値を文字で読む</summary><p>${g.traces.map(t=>`${esc(t.name)}：${g.durationMs}msに${t.cycles}周期、振幅の相対値${t.amplitude}`).join(' ／ ')}</p></details></figure>`;}
return out;}

function learn(){const a=state.active;if(!a)return home();const q=a.queue[a.index],u=unit(a.unit);return `<div class="row spread"><button class="quiet" data-pause>← 保存して中断</button><small>${a.index+1} / ${a.queue.length} 課題</small></div><div class="progress"><span style="width:${(a.index+(a.feedback?1:0))/a.queue.length*100}%"></span></div><section class="card"><div class="row spread"><span class="pill">${u.subject} · ${u.name}</span><small>${C.modes[q.mode]}</small></div>${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}${questionMedia(q)}<h2 class="prompt">${esc(q.prompt)}</h2>${a.feedback?'':q.options?`<div class="options">${q.options.map((o,i)=>`<button class="option" data-answer-index="${i}"><span>${i+1}</span>${esc(o)}</button>`).join('')}</div>`:`<form id="answer-form" class="input-row"><input id="answer-input" aria-label="${esc(q.inputLabel||'解答')}" inputmode="${q.grading==='number'||q.grading==='short_text'?'text':'decimal'}" autocomplete="off" value="${esc(a.draft)}" placeholder="${esc(q.inputPlaceholder||(q.grading==='number'?'整数・小数・分数':'数を入力'))}"><button type="submit">確かめる →</button></form>`}${a.inputError?`<p role="alert" class="notice">${esc(a.inputError)}</p>`:''}${!a.feedback?`<div class="row" style="margin-top:20px"><button class="quiet" data-hint>${a.hint&&q.hints?(a.hintStep>=q.hints.length?'ヒントを表示中':'次のヒントを見る'):'考え方をヒントにする'}</button><button class="quiet" data-unlearned>まだ習っていない</button></div>${a.hint?`<div class="notice">${q.hints?q.hints.slice(0,a.hintStep||1).map((h,i)=>`<p>ヒント${i+1}：${esc(h)}</p>`).join(''):u.lesson}</div>`:''}${a.taught?`<div class="notice"><strong>考え方の入口</strong><p>${u.lesson}</p>${a.unit==='math-equation'?'<p>例：2x＋3＝11なら、両辺から3を引いて2x＝8、両辺を2で割ってx＝4。元の式に4を入れて、左右が11になるか確かめます。</p>':''}</div><p class="subtle">説明を使って学習中。ポイントは変わりません。</p>`:''}`:`<div class="feedback ${a.feedback.ok?'':'review'}" role="status"><h3>${a.feedback.ok?'✓ 確かめられた！':'ここから、考え直そう。'}</h3><p><strong>${esc(a.feedback.answer)}</strong></p><p>${esc(a.feedback.explanation)}</p>${!a.feedback.ok?`<label class="checkline"><input type="checkbox" id="review-check" ${a.review?'checked':''}>考え方を確かめた</label>`:''}<button data-next ${!a.feedback.ok&&!a.review?'disabled':''}>${a.index+1===a.queue.length?'今回の発見を見る':'次の挑戦へ'} →</button></div>`}</section><p class="subtle">今回のセット完了で ${a.queue.length} pt。正解数・ヒント利用による減点はありません。</p>`;}
function spellCard(a){const date=state.awards.find(x=>x.id===a.id)?.at;return `<article class="award spell-card tone-${a.element}"><div class="spell-meta"><span>術式 ${String(E.awards.indexOf(a)+1).padStart(3,'0')}</span></div><div class="sigil"><span>${a.mark}</span></div><h3>${a.name}</h3><p>${a.incantation}</p><small>${date?fmt(date)+' 習得':''}</small></article>`;}

function abilities(){const subjects=['数学','英語','国語','理科','社会'],labels=['構築の知識','詠唱の知識','解読の知識','現象の知識','世界の知識'];return `<div class="abilities">${subjects.map((subject,i)=>{let us=C.units.filter(u=>u.subject===subject),ids=new Set(us.map(u=>u.id)),n=state.sessions.filter(x=>ids.has(x.unit)).length;return `<button data-subject="${subject}" class="ability"><span>${us[0].icon}</span><b>${labels[i]}</b><small>${subject} · 修練 ${n}回</small></button>`;}).join('')}</div>`;}
function collection(){const visible=state.awards.slice().reverse().map(x=>award(x.id)).filter(Boolean);let hints=E.awards.filter(a=>!state.awards.some(x=>x.id===a.id)).filter((a,i)=>i%5===0).slice(0,3);return `<div class="intro"><div><div class="eyebrow">YOUR PERSONAL GRIMOIRE</div><h1>自分だけの、魔導書。</h1><p class="muted">${visible.length}種の呪文を習得。</p></div></div><div class="card"><h3>魔法を支える知識</h3><p class="subtle">修練の記録が、知識として積み上がる。呪文の習得条件は、まだ秘密。</p>${abilities()}</div><div class="awardgrid">${visible.slice(0,collectionLimit).map(spellCard).join('')}${hints.map(a=>`<article class="award locked"><div class="sigil"><span>?</span></div><h3>封じられた術式</h3><p>${a.hint}</p><small>習得条件は未解明</small></article>`).join('')}</div>${visible.length>collectionLimit?'<button id="more-spells" class="secondary">さらに開く</button>':''}<p class="subtle">すべての術式が見えているわけではありません。新しい知識が、次の発見につながります。</p>`;}

function records(){return `<div class="intro"><div><div class="eyebrow">RECORD OF PRACTICE</div><h1>積み重ねは、残っている。</h1></div></div>${levelCard()}${numbers()}<div class="card"><h2>取り組んだ単元</h2><p class="subtle">${new Set(state.attempts.map(a=>a.unit)).size} / ${C.units.length} 単元に挑戦</p>${C.units.filter(u=>state.attempts.some(a=>a.unit===u.id)).map(u=>{let h=state.attempts.filter(a=>a.unit===u.id),p=E.progress(state,u.id);return `<div class="record row spread"><div><b>${u.name}</b><small>${p.label} · ${h.length}回の挑戦</small></div><a href="#unit/${u.id}">もう一度 ↗</a></div>`}).join('')}<p class="subtle">「複数の角度で確認」は、日を置いた自力の正解を含む状態です。単元全体の習得完了を意味しません。</p></div><div class="card"><h2>最近の修練</h2>${state.sessions.slice(-15).reverse().map(s=>`<div class="record"><b>${unit(s.unit).name}</b><small>${fmt(s.at)} · ${s.count}課題 · ${s.modes.map(m=>C.modes[m]).join(' / ')}</small></div>`).join('')||'<p class="muted">最初の一歩が、ここに記録されます。</p>'}</div>${state.legacy.length?`<div class="notice">旧版の解答履歴を ${state.legacy.length} 件保管しています。新しい習得判定とポイントには換算していません。</div>`:''}`;}
function family(){const p=E.totals(state),recent=state.awards.slice(-3).reverse().map(x=>award(x.id)).filter(Boolean);return `<section class="card family mage-profile"><div class="eyebrow">MAGE PORTRAIT</div><div class="mage-avatar" aria-hidden="true">✧</div><h1>${esc(state.name)}</h1><p class="muted">${state.awards.length}種の呪文を記した魔法使い</p>${levelCard()}<div class="eyebrow" style="margin-top:25px">今週の取り組み</div><div class="bigscore">${p.week}<small>pt</small></div><p class="muted">修練を終えた分だけ、積み上がる。</p><div class="sectionhead"><h2>最近習得した呪文</h2><a href="#collection">魔導書を見る ↗</a></div>${recent.length?`<div class="awardgrid">${recent.map(spellCard).join('')}</div>`:'<p class="subtle">修練で習得した呪文が、ここに記録されます。</p>'}${numbers()}<p class="subtle">レベル、習得した呪文、今週の取り組みを家族で見せ合おう。<br>週間集計は日本時間・月曜始まり。端末間の自動共有はありません。</p></section>`;}

function settings(){return `<div class="intro"><div><div class="eyebrow">MAGE SETTINGS</div><h1>記録・設定</h1></div></div><div class="card"><h2>プロフィール</h2><label for="name">表示名</label><div class="input-row"><input id="name" maxlength="24" value="${esc(state.name)}"><button id="save-name">保存</button></div></div><div class="card"><h2>記録を守る</h2><p class="subtle">機種変更やブラウザのデータ削除に備えて、ファイルで保存できます。復元前の記録を一つ退避してから置き換えます。間違えた場合は下の退避記録から戻せます。</p><div class="row"><button id="export">バックアップを書き出す</button><button class="secondary" id="restore">バックアップを復元</button><input id="import-file" type="file" accept=".json,application/json" hidden></div>${storageBlocked?'<button class="secondary" id="rescue">読み込めなかった保存データを救出</button>':''}</div>${recoveryPanel()}<div class="card"><h2>旧版の履歴を保管</h2><p class="subtle">旧アプリで書き出したJSONを取り込めます。原記録を保管し、新しいポイントや習得度には自動換算しません。</p><button class="secondary" id="legacy">旧版の記録を読み込む</button><input type="file" id="legacy-file" accept=".json,application/json" hidden></div><div class="card"><h2>お小遣いとの交換記録</h2><p class="subtle">換算レートは未設定です。家族で決めた後、実際に受け取った交換だけを記録してください。</p><p>交換可能：<b>${E.totals(state).balance} pt</b></p><label for="redeem-amount">交換に使ったポイント</label><input id="redeem-amount" type="number" min="1" step="1" placeholder="ポイント"><label for="redeem-note">メモ（任意）</label><input id="redeem-note" maxlength="100" placeholder="例：お小遣いを受け取った"><div><button class="secondary" id="redeem" style="margin-top:16px">交換を記録する</button></div>${state.ledger.filter(x=>x.kind==='redeem').slice(-8).reverse().map(x=>`<div class="record">${-x.amount} pt 交換<small>${fmt(x.at)} ${esc(x.note)}</small></div>`).join('')}</div>`;}
function done(){if(!lastResult)return home();const r=lastResult;return `<div class="card done"><div class="seal">✳</div><div class="eyebrow">PRACTICE COMPLETE</div><h1>知識が、魔法に変わる。</h1><p class="muted">${unit(r.unit).name}の挑戦を完了しました。</p><div class="score">+ ${r.amount} <small>pt</small></div><div class="subtle">+ ${r.xp} XP</div>${r.afterLevel>r.beforeLevel?`<div class="level-up">LEVEL UP · Lv. ${r.beforeLevel} → Lv. ${r.afterLevel}<br>${E.mageLevel(state).rank}</div>`:''}${levelCard()}${r.unlocked.length?`<div class="notice"><b>新しい呪文を習得しました！</b><p>${r.unlocked.map(id=>`${award(id).mark} ${award(id).name}`).join(' ／ ')}</p></div>`:''}<div class="row"><button data-go="collection" class="secondary">魔導書を開く</button><button data-start="">修練を続ける →</button><button class="secondary" data-go="explore">別の場所を探索</button><button class="quiet" data-go="home">今日はここまで</button></div><p class="subtle">続けた分だけ積み上がります。一日のポイント上限はありません。</p></div>`;}
function start(id,mode){if(storageBlocked){toast('記録・設定から保存データを復元してください。');return;}if(state.active){go('learn');toast('途中の学習を再開します。別の挑戦は中断画面から選べます。');return;}
let a=E.makeSession(state,id||null,mode||null);if(!a){modal('別の景色へ進もう','<p>この選び方では、今日の新しい課題を一巡しました。別の学び方や単元を選べます。日を置くと復習として戻れます。</p>');return;}state.active=a;save();go('learn');}
function download(obj,name){let url=URL.createObjectURL(new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){let route=location.hash.slice(1)||'home',page=route.split('/')[0];$('breadcrumb').textContent=({home:'今日の修練',explore:'知識の書庫',unit:'単元の入口',learn:'挑戦の途中',collection:'自分だけの魔導書',records:'学びの足跡',settings:'魔法使いの支度',family:'家族に見せる',done:'今回の成果'})[page]||'今日の修練';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(page==='unit'?'explore':page)));$('app').innerHTML=({home,explore,collection,records,settings,family,learn,done}[page]||(()=>unitPage(route.split('/')[1])))();bind();}
function bind(){
document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{filters={subject:b.dataset.subject,sub:'',grade:'',query:'',due:false,scope:false};go('explore');});
for(const k of ['subject','sub','grade','due','scope'])if($('filter-'+k))$('filter-'+k).onchange=e=>{filters[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(k==='subject')filters.sub='';render();};
if($('filter-query'))$('filter-query').oninput=e=>{filters.query=e.target.value.trim();const us=matchingUnits();$('unit-results').innerHTML=us.map(unitCard).join('')||'<p class="muted">該当する単元がありません。</p>';$('filter-count').textContent=us.length+'単元を表示 · テスト範囲は単元の入口で指定できます。';};
document.querySelectorAll('[data-exam-unit]').forEach(b=>b.onchange=()=>{const ids=new Set(state.examScope||[]);b.checked?ids.add(b.dataset.examUnit):ids.delete(b.dataset.examUnit);state.examScope=[...ids];save();});
if($('more-spells'))$('more-spells').onclick=()=>{collectionLimit+=24;render();};
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start,b.dataset.startMode));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(null,b.dataset.mode));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>go('learn'));document.querySelectorAll('[data-school]').forEach(b=>b.onclick=()=>{let [id,status]=b.dataset.school.split(':');state.school[id]={status,at:Date.now()};save();render();});
const pause=document.querySelector('[data-pause]');if(pause)pause.onclick=()=>{save();modal('途中の学習は保存しました','<p>後で同じところから再開できます。別の挑戦に切り替える場合は、このセットの未完了分を終了します。回答済みの履歴は残り、完了ポイントは付きません。</p><div class="row"><button id="pause-home">ホームへ</button><button class="secondary" id="switch-unit">このセットを終了して探索へ</button></div>');$('pause-home').onclick=()=>{$('dialog').close();go('home');};$('switch-unit').onclick=()=>{state.active=null;save();$('dialog').close();go('explore');};};
document.querySelectorAll('[data-answer-index]').forEach(b=>b.onclick=()=>{const a=state.active;E.answer(state,a.queue[a.index].options[+b.dataset.answerIndex]);save();render();});
if($('answer-input'))$('answer-input').oninput=e=>{state.active.draft=e.target.value;save();};if($('answer-form'))$('answer-form').onsubmit=e=>{e.preventDefault();E.answer(state,$('answer-input').value);save();render();};
const hint=document.querySelector('[data-hint]');if(hint)hint.onclick=()=>{state.active.hint=true;state.active.hintStep=Math.min((state.active.hintStep||0)+1,state.active.queue[state.active.index].hints?.length||1);save();render();};const untaught=document.querySelector('[data-unlearned]');if(untaught)untaught.onclick=()=>{state.active.taught=true;state.active.hint=true;state.active.hintStep=1;state.school[state.active.unit]={status:'unlearned',at:Date.now()};save();render();};
if($('review-check'))$('review-check').onchange=e=>{state.active.review=e.target.checked;save();document.querySelector('[data-next]').disabled=!e.target.checked;};const next=document.querySelector('[data-next]');if(next)next.onclick=()=>{let r=E.advance(state);save();if(r?.done){lastResult=r;go('done');}else render();};
if($('save-name'))$('save-name').onclick=()=>{state.name=$('name').value.trim()||'見習い魔法使い';save();toast('表示名を保存しました。');};if($('export'))$('export').onclick=()=>download(state,'study-trail-backup-'+E.day(Date.now())+'.json');if($('rescue'))$('rescue').onclick=()=>download(localStorage.getItem(KEY)||'','study-trail-rescue.json');
if($('restore'))$('restore').onclick=()=>$('import-file').click();if($('import-file'))$('import-file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('20MB以下のファイルを指定してください。');pendingImport=E.validate(JSON.parse(await f.text()));modal('バックアップを復元しますか？',`<p>${esc(pendingImport.name)}の ${pendingImport.sessions.length} セットの記録です。現在の記録を退避してから置き換えます。ファイルでも残しておくと安心です。</p><button id="confirm-import">この内容に置き換える</button>`);$('confirm-import').onclick=()=>{try{state=recovery.replace(pendingImport);}catch(e){toast('現在の記録の退避または保存ができないため、復元を中止しました。');return;}storageBlocked=false;pendingImport=null;$('storage-warning').textContent='';$('dialog').close();render();toast('復元しました。');};}catch(err){modal('読み込めません',`<p>${esc(err.message)}</p>`);}};
if($('export-recovery'))$('export-recovery').onclick=()=>{try{const item=recovery.inspect();if(item)download(item.raw,'study-trail-before-restore.json');}catch(e){toast('退避記録を読み込めません。');}};
if($('undo-restore'))$('undo-restore').onclick=()=>{try{const item=recovery.inspect();if(!item?.state)throw Error('退避記録を復元できません。');modal('置き換える前に戻しますか？',`<p>${esc(item.state.name)}の ${item.state.sessions.length} セットの記録に戻します。現在の記録を新しい退避として残します。</p><button id="confirm-undo">この記録に戻す</button>`);$('confirm-undo').onclick=()=>{try{state=recovery.undo();storageBlocked=false;$('storage-warning').textContent='';$('dialog').close();render();toast('置き換える前の記録に戻しました。');}catch(e){toast('退避または保存ができないため中止しました。');}};}catch(e){toast(e.message);}};
if($('legacy'))$('legacy').onclick=()=>$('legacy-file').click();if($('legacy-file'))$('legacy-file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('20MB以下を指定してください。');let v=JSON.parse(await f.text());if(v.kind!=='midterm-backup'||![1,2].includes(v.schemaVersion)||!Array.isArray(v.history)||v.history.length>100000||v.history.some(x=>!x||typeof x.skill!=='string'||typeof x.ok!=='boolean'||!Number.isFinite(x.at)))throw Error('旧版の全記録バックアップを指定してください。');let seen=new Set(state.legacy.map(x=>JSON.stringify(x)));for(const x of v.history){let k=JSON.stringify(x);if(!seen.has(k)){state.legacy.push(x);seen.add(k);}}save();render();toast('旧版の履歴を保管しました。');}catch(err){modal('読み込めません',`<p>${esc(err.message)}</p>`);}};
if($('redeem'))$('redeem').onclick=()=>{let amount=Number($('redeem-amount').value),note=$('redeem-note').value;if(!Number.isSafeInteger(amount)||amount<=0||amount>E.totals(state).balance){toast('残高以内の正の整数を入力してください。');return;}modal('受け取りを確認',`<p>${amount} pt を交換済みとして記録します。実際のお小遣いは受け取りましたか？</p><button id="confirm-redeem">受け取ったので記録する</button>`);$('confirm-redeem').onclick=()=>{try{E.redeem(state,amount,note);save();$('dialog').close();render();}catch(e){toast(e.message);}};};}
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{state=E.validate(JSON.parse(e.newValue));render();toast('別のタブで保存された最新の記録に更新しました。');}catch(err){storageBlocked=true;$('storage-warning').textContent='別のタブの記録を読み込めません。バックアップ後に再読み込みしてください。';}});
window.addEventListener('hashchange',render);render();
})();
